package com.example.editor.grammar.provider.xtext;

import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;
import com.example.editor.grammar.GrammarProperties;
import com.example.editor.grammar.core.*;
import com.example.editor.grammar.provider.*;

/** Xtext provider around the JVM/LSP runtime. The deprecated xtext-web stack is deliberately excluded. */
@Component
public class XtextGrammarProvider extends AbstractNeutralGrammarProvider {
    private static final Pattern GRAMMAR_NAME=Pattern.compile("(?m)^\\s*grammar\\s+([A-Za-z_][A-Za-z0-9_.]*)\\b");
    /** Descripción: Inicializa una instancia de XtextGrammarProvider con sus dependencias y datos de entrada. Entradas: properties: configuración que gobierna el comportamiento. Salida: deja la instancia inicializada y lista para su uso. */ public XtextGrammarProvider(GrammarProperties properties) { super(properties); }

    /** Descripción: Ejecuta la operación «descriptor» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public GrammarProviderDescriptor descriptor() {
        return new GrammarProviderDescriptor("xtext", GrammarTechnology.XTEXT, "Xtext", "hydra-provider-1.0",
                new GrammarProviderCapabilities(EnumSet.of(
                        GrammarProviderCapability.ANALYZE, GrammarProviderCapability.CODE_ACTIONS,
                        GrammarProviderCapability.SEMANTIC_MAPPING, GrammarProviderCapability.PROJECT_GENERATION,
                        GrammarProviderCapability.TEXTUAL_RUNTIME, GrammarProviderCapability.COMPLETION,
                        GrammarProviderCapability.HOVER, GrammarProviderCapability.DEFINITION, GrammarProviderCapability.REFERENCES,
                        GrammarProviderCapability.RENAME, GrammarProviderCapability.FORMATTING, GrammarProviderCapability.FOLDING,
                        GrammarProviderCapability.DOCUMENT_SYMBOLS, GrammarProviderCapability.SEMANTIC_TOKENS,
                        GrammarProviderCapability.ECORE_INFERENCE, GrammarProviderCapability.ECORE_IMPORT,
                        GrammarProviderCapability.LANGUAGE_SERVER, GrammarProviderCapability.JVM_RUNTIME,
                        GrammarProviderCapability.STANDALONE_DESKTOP),
                        List.of("Java"), List.of("maven"),
                        EnumSet.of(GrammarProviderCapability.ANALYZE, GrammarProviderCapability.CODE_ACTIONS,
                                GrammarProviderCapability.SEMANTIC_MAPPING, GrammarProviderCapability.PROJECT_GENERATION,
                                GrammarProviderCapability.TEXTUAL_RUNTIME),
                        EnumSet.of(GrammarProviderCapability.COMPLETION, GrammarProviderCapability.HOVER,
                                GrammarProviderCapability.DEFINITION, GrammarProviderCapability.REFERENCES, GrammarProviderCapability.RENAME,
                                GrammarProviderCapability.FORMATTING, GrammarProviderCapability.FOLDING,
                                GrammarProviderCapability.DOCUMENT_SYMBOLS, GrammarProviderCapability.SEMANTIC_TOKENS,
                                GrammarProviderCapability.ECORE_INFERENCE, GrammarProviderCapability.ECORE_IMPORT,
                                GrammarProviderCapability.LANGUAGE_SERVER, GrammarProviderCapability.JVM_RUNTIME,
                                GrammarProviderCapability.STANDALONE_DESKTOP)),
                List.of("FAST","NORMAL","FULL"),
                Map.of("nativeValidation","MWE2_XTEXT_GENERATOR","deployment.browser","REQUIRES_JVM_LSP",
                        "deployment.desktop","FULL","deployment.offlinePwa","NOT_SUPPORTED","xtextWeb","false"));
    }

    /** Descripción: Crea o prepara el resultado de «generateProject» dentro de XtextGrammarProvider. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ @Override public GeneratedGrammarProject generateProject(GrammarProjectGenerationRequest request) {
        GrammarSourceDocument entry=entry(request);
        String grammarName=grammarName(entry.content());
        if(grammarName.isBlank())throw new IllegalArgumentException("Xtext entry document must declare a grammar name");
        String base=mavenId(request.grammar().id().isBlank()?grammarName.toLowerCase(Locale.ROOT):request.grammar().id());
        String version=request.profile().runtimeVersion();
        String extension=extensionId(request.grammar().id());
        Map<String,String> scaffold=new LinkedHashMap<>();
        scaffold.put("pom.xml",parentPom(base,version,javaRelease(request.profile())));
        scaffold.put("src/main/mwe2/GenerateLanguage.mwe2",workflow(base,grammarName,extension));
        scaffold.put(base+"/pom.xml",runtimePom(base,version));
        scaffold.put(base+".ide/pom.xml",idePom(base,version));
        scaffold.put(base+".tests/pom.xml",testsPom(base,version));
        scaffold.put(base+"/src/main/java/"+grammarName.replace('.','/')+".xtext",entry.content());
        scaffold.put(base+".tests/src/test/java/hydra/generated/HydraXtextGenerationSmokeTest.java",smoke(base,request));
        scaffold.put("HYDRA_PROVENANCE.properties","grammarId="+propertiesValue(request.grammar().id())+"\nsourceHash="+GrammarHashing.sources(request.documents())+"\ntoolchainProfile="+propertiesValue(request.profile().id())+"\nproviderVersion="+propertiesValue(request.profile().providerVersion())+"\ngrammarName="+propertiesValue(grammarName)+"\nxtextWeb=false\ngenerator=MWE2_XTEXT_GENERATOR\n");
        return project(request,scaffold);
    }

    /** Descripción: Procesa la operación «runtimeDescriptor» coordinando las responsabilidades de XtextGrammarProvider. Entradas: grammar: dato de entrada necesario para la operación; profile: archivo o contenido que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ @Override public GrammarRuntimeDescriptor runtimeDescriptor(GrammarDefinitionModel grammar, GrammarToolchainProfile profile) {
        return new GrammarRuntimeDescriptor("XTEXT_JVM_LSP", grammar.entryRule(), List.of("."+extensionId(grammar.id())),
                "java -jar language-server.jar", "", Map.of("provider","XTEXT","runtimeProfileKey","xtext","providerVersion",profile.providerVersion(),"offlinePwa","false","xtextWeb","false"));
    }
    /** Descripción: Ejecuta la operación «syntaxMetadata» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ @Override public GrammarSyntaxMetadata syntaxMetadata() { return new GrammarSyntaxMetadata("xtext", List.of("grammar","with","generate","import","returns","terminal","enum","fragment","hidden","current"), Map.of("rule","type","terminal","regexp"), List.of(".xtext")); }

    /** Descripción: Ejecuta la operación «entry» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static GrammarSourceDocument entry(GrammarProjectGenerationRequest request){return request.documents().stream().filter(GrammarSourceDocument::entryPoint).findFirst().orElseGet(()->request.documents().stream().findFirst().orElseThrow(()->new IllegalArgumentException("Xtext project generation requires an entry document")));}
    /** Descripción: Ejecuta la operación «grammarName» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: source: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String grammarName(String source){Matcher matcher=GRAMMAR_NAME.matcher(source==null?"":source);return matcher.find()?matcher.group(1):"";}
    /** Descripción: Ejecuta la operación «javaRelease» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: profile: archivo o contenido que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String javaRelease(GrammarToolchainProfile profile){String value=profile.javaVersion();if(value==null||value.isBlank())return "17";var matcher=Pattern.compile("(\\d+)").matcher(value);return matcher.find()?matcher.group(1):"17";}
    /** Descripción: Ejecuta la operación «workflow» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: base: dato de entrada necesario para la operación; grammarName: dato de entrada necesario para la operación; extension: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String workflow(String base,String grammarName,String extension){return "module hydra.generated.GenerateLanguage\n\nimport org.eclipse.xtext.xtext.generator.*\nimport org.eclipse.xtext.xtext.generator.model.project.*\n\nvar rootPath = \".\"\n\nWorkflow {\n  component = XtextGenerator {\n    configuration = {\n      project = StandardProjectConfig {\n        baseName = \""+mwe(base)+"\"\n        rootPath = rootPath\n        runtime = { enabled = true }\n        runtimeTest = { enabled = true }\n        genericIde = { enabled = true }\n        eclipsePlugin = { enabled = false }\n        eclipsePluginTest = { enabled = false }\n        createEclipseMetaData = false\n      }\n      code = { encoding = \"UTF-8\" lineDelimiter = \"\\n\" }\n    }\n    language = StandardLanguage {\n      name = \""+mwe(grammarName)+"\"\n      fileExtensions = \""+mwe(extension)+"\"\n      serializer = { generateStub = false }\n      validator = { generateStub = false }\n    }\n  }\n}\n";}
    /** Descripción: Ejecuta la operación «parentPom» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: base: dato de entrada necesario para la operación; version: dato de entrada necesario para la operación; javaRelease: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String parentPom(String base,String version,String javaRelease){return "<project xmlns=\"http://maven.apache.org/POM/4.0.0\"><modelVersion>4.0.0</modelVersion><groupId>hydra.generated</groupId><artifactId>"+xml(base)+".parent</artifactId><version>1.0.0-SNAPSHOT</version><packaging>pom</packaging>"+
            "<properties><xtext.version>"+xml(version)+"</xtext.version><maven.compiler.release>"+xml(javaRelease)+"</maven.compiler.release><project.build.sourceEncoding>UTF-8</project.build.sourceEncoding></properties>"+
            "<modules><module>"+xml(base)+"</module><module>"+xml(base)+".ide</module><module>"+xml(base)+".tests</module></modules>"+
            "<build><plugins><plugin><groupId>org.codehaus.mojo</groupId><artifactId>exec-maven-plugin</artifactId><version>3.6.3</version><executions><execution><id>xtext-generate-language</id><phase>generate-sources</phase><goals><goal>java</goal></goals></execution></executions><configuration><mainClass>org.eclipse.emf.mwe2.launch.runtime.Mwe2Launcher</mainClass><arguments><argument>${project.basedir}/src/main/mwe2/GenerateLanguage.mwe2</argument><argument>-p</argument><argument>rootPath=${project.basedir}</argument></arguments><classpathScope>compile</classpathScope></configuration><dependencies><dependency><groupId>org.eclipse.xtext</groupId><artifactId>org.eclipse.xtext.xtext.generator.dependencies</artifactId><version>${xtext.version}</version></dependency></dependencies></plugin></plugins></build></project>\n";}
    /** Descripción: Procesa la operación «runtimePom» coordinando las responsabilidades de XtextGrammarProvider. Entradas: base: dato de entrada necesario para la operación; version: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String runtimePom(String base,String version){return moduleHeader(base,base)+"<dependencies><dependency><groupId>org.eclipse.xtext</groupId><artifactId>org.eclipse.xtext</artifactId><version>"+xml(version)+"</version></dependency><dependency><groupId>org.eclipse.xtext</groupId><artifactId>org.eclipse.xtext.common.types</artifactId><version>"+xml(version)+"</version></dependency></dependencies>"+sourceRoots()+"</project>\n";}
    /** Descripción: Ejecuta la operación «idePom» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: base: dato de entrada necesario para la operación; version: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String idePom(String base,String version){return moduleHeader(base,base+".ide")+"<dependencies><dependency><groupId>hydra.generated</groupId><artifactId>"+xml(base)+"</artifactId><version>1.0.0-SNAPSHOT</version></dependency><dependency><groupId>org.eclipse.xtext</groupId><artifactId>org.eclipse.xtext.ide</artifactId><version>"+xml(version)+"</version></dependency></dependencies>"+sourceRoots()+"</project>\n";}
    /** Descripción: Ejecuta la operación «testsPom» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: base: dato de entrada necesario para la operación; version: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String testsPom(String base,String version){return moduleHeader(base,base+".tests")+"<dependencies><dependency><groupId>hydra.generated</groupId><artifactId>"+xml(base)+"</artifactId><version>1.0.0-SNAPSHOT</version></dependency><dependency><groupId>org.eclipse.xtext</groupId><artifactId>org.eclipse.xtext.testing</artifactId><version>"+xml(version)+"</version><scope>test</scope></dependency><dependency><groupId>org.junit.jupiter</groupId><artifactId>junit-jupiter</artifactId><version>5.12.2</version><scope>test</scope></dependency></dependencies><build><plugins><plugin><groupId>org.apache.maven.plugins</groupId><artifactId>maven-surefire-plugin</artifactId><version>3.5.3</version></plugin></plugins></build></project>\n";}
    /** Descripción: Ejecuta la operación «moduleHeader» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: base: dato de entrada necesario para la operación; artifact: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String moduleHeader(String base,String artifact){return "<project xmlns=\"http://maven.apache.org/POM/4.0.0\"><modelVersion>4.0.0</modelVersion><parent><groupId>hydra.generated</groupId><artifactId>"+xml(base)+".parent</artifactId><version>1.0.0-SNAPSHOT</version></parent><artifactId>"+xml(artifact)+"</artifactId>";}
    /** Descripción: Ejecuta la operación «sourceRoots» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ private static String sourceRoots(){return "<build><plugins><plugin><groupId>org.codehaus.mojo</groupId><artifactId>build-helper-maven-plugin</artifactId><version>3.6.1</version><executions><execution><id>add-xtext-generated</id><phase>generate-sources</phase><goals><goal>add-source</goal></goals><configuration><sources><source>src-gen</source></sources></configuration></execution></executions></plugin></plugins></build>";}
    /** Descripción: Ejecuta la operación «smoke» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: base: dato de entrada necesario para la operación; request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ private static String smoke(String base,GrammarProjectGenerationRequest request){return "package hydra.generated; import static org.junit.jupiter.api.Assertions.*; import java.nio.file.*; import org.junit.jupiter.api.Test; class HydraXtextGenerationSmokeTest { @Test void generatedRuntimeIsPresent(){ assertTrue(Files.isDirectory(Path.of(\"../"+javaString(base)+"/src-gen\"))); assertFalse(\""+javaString(request.profile().id())+"\".isBlank()); } }\n";}
    /** Descripción: Ejecuta la operación «mavenId» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String mavenId(String value){String result=(value==null?"":value).toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_.-]+","-").replaceAll("^-+|-+$","");return result.isBlank()?"hydra.xtext.language":result;}
    /** Descripción: Ejecuta la operación «extensionId» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String extensionId(String value){String result=(value==null?"":value).toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","");return result.isBlank()?"dsl":result;}
    /** Descripción: Ejecuta la operación «xml» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String xml(String value){return value==null?"":value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
    /** Descripción: Ejecuta la operación «mwe» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String mwe(String value){return value==null?"":value.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ").replace("\r"," ");}
    /** Descripción: Ejecuta la operación «javaString» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String javaString(String value){return value==null?"":value.replace("\\","\\\\").replace("\"","\\\"").replace("\n"," ").replace("\r"," ");}
    /** Descripción: Ejecuta la operación «propertiesValue» correspondiente a la responsabilidad de XtextGrammarProvider. Entradas: value: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ private static String propertiesValue(String value){return value==null?"":value.replace("\n"," ").replace("\r"," ").replace("=","\\=");}
}
